<?php
require __DIR__.'/config.php'; $pdo=db(); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(($_POST['action']??'')==='add'){ $id=(int)($_POST['product_id']??0); $s=$pdo->prepare("SELECT id,stock FROM products WHERE id=? AND active=1");$s->execute([$id]);$p=$s->fetch();if($p && $p['stock']>0){$_SESSION['cart'][$id]=min((int)$p['stock'],(int)($_SESSION['cart'][$id]??0)+1);flash('Product added to your cart.');} }
 if(($_POST['action']??'')==='update'){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,99);}flash('Cart updated.');}
 if(($_POST['action']??'')==='remove'){unset($_SESSION['cart'][(int)$_POST['product_id']]);flash('Item removed.');}
 header('Location: cart.php');exit;
}
$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;
if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$s->execute($ids);foreach($s as $p){$p['qty']=(int)$cart[$p['id']];$p['line']=$p['qty']*(float)$p['price'];$subtotal+=$p['line'];$items[]=$p;}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your Cart — Aastha</title><link rel="stylesheet" href="assets/css/store.css"></head><body><header class="simple-head wrap"><a class="brand" href="index.php"><span class="brand-mark">A</span><span>Aastha<small>FRESH EVERY DAY</small></span></a><a href="index.php">← Continue shopping</a></header><main class="wrap page-main"><span class="eyebrow">YOUR BASKET</span><h1>Shopping cart</h1><?php show_flash(); if(!$items): ?><div class="empty-state"><h2>Your cart is waiting</h2><p>Add your everyday essentials to get started.</p><a class="green-btn" href="index.php#products">Shop products →</a></div><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><div class="cart-layout"><div class="cart-items"><?php foreach($items as $p): ?><div class="cart-item"><div class="cart-thumb"><?=e(mb_substr($p['name'],0,1))?></div><div class="cart-description"><b><?=e($p['name'])?></b><small><?=e($p['unit'])?></small><strong><?=money((float)$p['price'])?></strong></div><label>Qty <input type="number" min="0" max="99" name="qty[<?=(int)$p['id']?>]" value="<?=(int)$p['qty']?>"></label><b><?=money($p['line'])?></b></div><?php endforeach; ?><button class="outline-btn">Update cart</button></div><aside class="summary"><h2>Order summary</h2><p><span>Subtotal</span><b><?=money($subtotal)?></b></p><p><span>Delivery</span><b>Calculated at checkout</b></p><div class="summary-total"><span>Total</span><b><?=money($subtotal)?></b></div><a class="green-btn full" href="checkout.php">Proceed to checkout →</a></aside></div></form><?php endif; ?></main></body></html>